<?php require_once dirname(__DIR__).'/includes/functions.php';require_admin();$rows=$con->query('SELECT l.*,u.name admin_name FROM admin_logs l JOIN users u ON u.id=l.admin_id ORDER BY l.created_at DESC LIMIT 500');$pageTitle='Admin logs';require __DIR__.'/includes/header.php';?><h1 class="h3">Admin audit log</h1><p class="text-muted">Read-only record of administrative changes.</p><div class="card table-responsive"><table class="table mb-0"><thead><tr><th>Time</th><th>Admin</th><th>Action</th><th>Target</th><th>Details</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['created_at'])?></td><td><?=e($r['admin_name'])?></td><td><?=e($r['action'])?></td><td><?=e($r['target_type'])?> #<?=$r['target_id']?></td><td><?=e($r['details'])?></td></tr><?php endforeach?></tbody></table></div><?php require __DIR__.'/includes/footer.php';?>
